import{_ as e,o as n,c as i,a1 as t}from"./chunks/framework.DxqwKiYY.js";const s="/pelatihan-webgis-big/assets/image1.D0fM8Zpe.png",r="/pelatihan-webgis-big/assets/image2.B-w4JFjE.png",p="/pelatihan-webgis-big/assets/image3.DIDu_Rc9.png",g="/pelatihan-webgis-big/assets/image4.BiiVVq3Z.png",l="/pelatihan-webgis-big/assets/image5.Cnay-HAd.png",m="/pelatihan-webgis-big/assets/image6.Dgn680zR.png",u="/pelatihan-webgis-big/assets/image7.3ech4ujH.png",d="/pelatihan-webgis-big/assets/image8.BnyAa9k8.png",o="/pelatihan-webgis-big/assets/image9.BkefF4ww.png",k="/pelatihan-webgis-big/assets/image10.Bg4OfoAW.png",b="data:image/png;base64,",h="/pelatihan-webgis-big/assets/image12.DJ3KjsR-.png",c="/pelatihan-webgis-big/assets/image13.DCxcafEV.png",f="/pelatihan-webgis-big/assets/image14.D19ccna4.png",A="/pelatihan-webgis-big/assets/image15.DSPux5Ae.png",R="/pelatihan-webgis-big/assets/image16.BY4TjR7e.png",I="/pelatihan-webgis-big/assets/image17.Dq0HWezO.png",w=JSON.parse('{"title":"Menampilkan Data Raster","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Menampilkan Data Raster.md","filePath":"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Menampilkan Data Raster.md"}'),D={name:"Training WebGIS BIG/Modul 2 - Pengembangan Frontend Peta 2D/Menampilkan Data Raster.md"};function F(x,a,y,P,E,j){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="menampilkan-data-raster" tabindex="-1">Menampilkan Data Raster <a class="header-anchor" href="#menampilkan-data-raster" aria-label="Permalink to &quot;Menampilkan Data Raster&quot;">​</a></h1><p><strong>Menampilkan data raster</strong></p><ol><li><p>Tahap pertama install library untuk menampilkan raster menggunakan leaflet dengan menginput perintah pada terminal <strong>npm install georaster georaster-layer-for-leaflet</strong>.</p><p><img src="'+s+'" alt=""></p></li><li><p>Pada tahap kedua buat file baru pada folder layer dengan nama Raster.jsx kemudian buat fungsi baru untuk menambahkan data raster kedalam peta serta tambahkan paramter urlTiff.</p><p><img src="'+r+'" alt=""></p></li><li><p>Selanjutnya buat fungsi <strong>return fetch</strong> untuk mengambil data raster yang akan digunakan promise berupa return untuk menampilkan layer dalam peta.</p><p><img src="'+p+'" alt=""></p></li><li><p>Tahapan ketiga buat fungsi <strong>.then(response)</strong> untuk melanjutkan proses setelah file selesai diambil response yang berisi hasil dari proses pengambilan file TIFF.</p><p><img src="'+g+'" alt=""></p></li><li><p>Pada tahap keempat didalam fungsi sebelumnya, buat fungsi yang digunakan untuk melakukan pemeriksaan file apakah dapat ditemukan atau tidak dengan membuat fungsi kondisional <strong>if.</strong></p><p><img src="'+l+'" alt=""></p></li><li><p>Pada tahap kelima buat fungsi untuk mengembalikan dan memproses data tiff jika berhasil diproses dengan menggunakan <strong>return</strong>.</p><p><img src="'+m+'" alt=""></p></li><li><p>Tahap keenam buat kembali fungsi <strong>.then</strong> yang akan digunakan untuk mengkonversi data tiff menjadi data raster yang dapat dibaca dan diproses oleh library leaflet.</p><p><img src="'+u+'" alt=""></p></li><li><p>Kemudian buat kembali <strong>.then</strong> untuk mengambil data raster yang sudah dibaca sehingga dapat ditampilkan dalam layer. Kemudian tambahkan opacity digunakan untuk mengatur transparansi raster, serta resolution digunakan untuk mengatur tingkat detail saat raster ditampilkan.</p><p><img src="'+d+'" alt=""></p></li><li><p>Kemudian tahapan berikutnya buat fungsi catch( ) yang digunakan untuk menangani jika terjadi kesalahan atau jika file gagal dimuat.</p><p><img src="'+o+'" alt=""></p></li><li><p>Berikut ini hasil keseluruhan script fungsi untuk menambahkan data raster pada file RasterTif.jsx</p><p><img src="'+k+'" alt=""></p></li><li><p>Berikutnya, masukan data raster yang dimiliki kedalam folder data yang terdapat dalam folder public.</p><p><img src="'+b+'" alt=""></p></li><li><p>Kemudian tahap terakhir panggil fungsi untuk menampilkan data raster dalam halaman Map.jsx dengan menggunakan addRasterTif, lalu tambahkan parameter berupa path dari folder tempat penyimpanan data raster, kemudian tambahkan fungsi untuk autozoom kearea layer tersebut dengan fungsi <strong>getbound</strong></p><p><img src="'+h+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi <strong>map.on</strong> untuk mengetahui layer yang sedang diaktifkan, kemudian tambahkan parameter overlayed sebagai parameter overlay yang ada pada layer control.</p><p><img src="'+c+'" alt=""></p></li><li><p>Kemudian didalam <strong>map.on</strong> buat fungsi berupa kondisi <strong>if</strong> untuk mengetahui apakah terdapat layer yang memiliki <strong>custom bound</strong>.</p><p><img src="'+f+'" alt=""></p></li><li><p>Selanjutnya tambahkan fungsi pada kondisi tersebut jika layer miliki custom bound maka tampilan peta akan menyesuaikan berdasarkan customBounds.</p><p><img src="'+A+'" alt=""></p></li><li><p>Kemudian buat kondisi kedua menggunakan <strong>else</strong> jika tidak memiliki customBounds, script mengecek apakah layer memiliki fungsi getBounds() untuk mendapatkan batas geografis layer.</p><p><img src="'+R+'" alt=""></p></li><li><p>Hasil tampilan data raster yang dimuat pada halaman webgis dapat dilihat pada gambar berikut ini.</p><p><img src="'+I+'" alt=""></p></li></ol>',3)])])}const H=e(D,[["render",F]]);export{w as __pageData,H as default};
